import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] a = new long[n];
        for(int i = 0; i < n; i++) {
            a[i] = sc.nextLong();
        }
        long best = a[0];
        long cur = a[0];
        for(int i = 1; i < n; i++) {
            if(cur < 0) {
                cur = a[i];
            } else {
                cur = cur + a[i];
            }
            if(cur > best) {
                best = cur;
            }
        }
        System.out.println(best);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] code = new int[n];
        for(int i = 0; i < n; i++) {
            code[i] = sc.nextInt();
        }
        int answer = -1;
        for(int i = 0; i < n && answer == -1; i++) {
            int count = 0;
            for(int j = 0; j < n; j++) {
                if(code[j] == code[i]) {
                    count++;
                }
            }
            if(count > n / 2) {
                answer = code[i];
            }
        }
        System.out.println(answer);
    }
}

